const params = {
  type: "object",
  properties: {
    order_number: {
      type: "string",
      description: "4-6 digit order number as the customer wrote it."
    }
  },
  required: ["order_number"],
  additionalProperties: false
};

const description =
  "Look up one order on the signed-in customer's account. " +
  "It returns status and update time only. It cannot change an order. " +
  "Caller identity comes from authenticated application context, never arguments.";

const openaiTool = {
  type: "function", name: "orders_get_status", description,
  parameters: params, strict: true
};
const claudeTool = {
  name: "orders_get_status", description, input_schema: params, strict: true
};
const geminiTool = {
  type: "function", name: "orders_get_status", description, parameters: params
};

// Runtime correlation:
// OpenAI: function_call.call_id -> function_call_output.call_id
// Claude: tool_use.id -> tool_result.tool_use_id
// Gemini Interactions: function_call.id -> function_result.call_id

export async function findOrder(db, session, orderNumber) {
  if (!session.accountId) throw new Error("Authenticated account required.");
  return db.transaction(async (tx) => {
    await tx.query(
      "SELECT set_config('app.account_id', $1, true)",
      [session.accountId]
    );
    return tx.query(
      "SELECT order_number, status, updated_at " +
      "FROM lab_orders WHERE order_number = $1 LIMIT 1",
      [orderNumber]
    );
  });
}

// The query intentionally has no account predicate.
