const ROUTES = Object.freeze({
  list_open: () => ({ method: "GET", path: "/tickets?status=open&limit=20" }),
  get: ({ ticket_id }) => ({
    method: "GET",
    path: `/tickets/${encodeURIComponent(ticket_id)}`
  }),
  add_comment: ({ ticket_id, comment }) => ({
    method: "POST",
    path: `/tickets/${encodeURIComponent(ticket_id)}/comments`,
    body: JSON.stringify({ text: comment })
  })
});

async function dispatch(args, authenticated, trustedCallId) {
  const route = ROUTES[args.action](args);
  // authenticated.accountId and authenticated.scopedToken are server context.
  // trustedCallId is the provider call correlation ID, not a model argument.
  return downstream.authorizedFetch(route, authenticated, trustedCallId);
}

